	ring_slash_glow = "rbxassetid://0", -- textures/ring_slash_glow.png
	ring_slash_rim = "rbxassetid://0", -- textures/ring_slash_rim.png
	ring_slash_mid = "rbxassetid://0", -- textures/ring_slash_mid.png
	ring_slash_core = "rbxassetid://0", -- textures/ring_slash_core.png
	glint = "rbxassetid://0", -- textures/glint.png
}

local function NS(k) local t = {} for i, p in k do t[i] = NumberSequenceKeypoint.new(p[1], p[2], p[3] or 0) end return NumberSequence.new(t) end
local function CS(k) local t = {} for i, p in k do t[i] = ColorSequenceKeypoint.new(p[1], Color3.fromHex(p[2])) end return ColorSequence.new(t) end

